<?php defined('ABSPATH')||exit;?>
<div class="woocommerce-checkout-review-order-table juhani-order-review"><div class="jop-mini-items">
<?php do_action('woocommerce_review_order_before_cart_contents');foreach(WC()->cart->get_cart() as $key=>$item):$product=apply_filters('woocommerce_cart_item_product',$item['data'],$item,$key);if(!$product||!$product->exists()||$item['quantity']<=0||!apply_filters('woocommerce_checkout_cart_item_visible',true,$item,$key))continue;?>
<article class="jop-mini-item"><div class="jop-mini-image"><?php echo $product->get_image('woocommerce_thumbnail');?></div><div><h3><?php echo wp_kses_post(apply_filters('woocommerce_cart_item_name',$product->get_name(),$item,$key));?></h3><?php juhani_order_spec_chips($item,'jop-mini-specs');?><div class="juhani-checkout-quantity"><span>Qty:</span><button type="button" data-order-step="-1" data-cart-key="<?php echo esc_attr($key);?>" data-quantity="<?php echo esc_attr($item['quantity']);?>" aria-label="Decrease quantity">−</button><span><?php echo esc_html($item['quantity']);?></span><button type="button" data-order-step="1" data-cart-key="<?php echo esc_attr($key);?>" data-quantity="<?php echo esc_attr($item['quantity']);?>" aria-label="Increase quantity">+</button></div></div><strong><?php echo apply_filters('woocommerce_cart_item_subtotal',WC()->cart->get_product_subtotal($product,$item['quantity']),$item,$key);?></strong></article>
<?php endforeach;do_action('woocommerce_review_order_after_cart_contents');?></div>
<table class="shop_table juhani-order-totals"><tbody><tr class="cart-subtotal"><th>Subtotal</th><td><?php wc_cart_totals_subtotal_html();?></td></tr>
<?php foreach(WC()->cart->get_coupons() as $code=>$coupon):?><tr class="cart-discount coupon-<?php echo esc_attr(sanitize_title($code));?>"><th><?php wc_cart_totals_coupon_label($coupon);?></th><td><?php wc_cart_totals_coupon_html($coupon);?></td></tr><?php endforeach;?>
<?php if(WC()->cart->needs_shipping()&&WC()->cart->show_shipping()):do_action('woocommerce_review_order_before_shipping');wc_cart_totals_shipping_html();do_action('woocommerce_review_order_after_shipping');elseif(WC()->cart->needs_shipping()):?><tr class="shipping"><th>Delivery</th><td>Calculated from your delivery details</td></tr><?php endif;?>
<?php foreach(WC()->cart->get_fees() as $fee):?><tr class="fee"><th><?php echo esc_html($fee->name);?></th><td><?php wc_cart_totals_fee_html($fee);?></td></tr><?php endforeach;?>
<?php if(wc_tax_enabled()&&!WC()->cart->display_prices_including_tax()):if(get_option('woocommerce_tax_total_display')==='itemized'):foreach(WC()->cart->get_tax_totals() as $tax):?><tr class="tax-rate"><th><?php echo esc_html($tax->label);?></th><td><?php echo wp_kses_post($tax->formatted_amount);?></td></tr><?php endforeach;else:?><tr class="tax-total"><th><?php echo esc_html(WC()->countries->tax_or_vat());?></th><td><?php wc_cart_totals_taxes_total_html();?></td></tr><?php endif;endif;?>
<?php do_action('woocommerce_review_order_before_order_total');?><tr class="order-total"><th>Total to pay</th><td><?php wc_cart_totals_order_total_html();?></td></tr><?php do_action('woocommerce_review_order_after_order_total');?></tbody></table></div>
